clc; clear;

figureDir = "figures";
if ~isfolder(figureDir)
    mkdir(figureDir);
end

opsMAT = OpenSeesMatlab;
ops = opsMAT.opensees;
opsvis = opsMAT.vis;
%%
%[text] 
%[text] 
params = struct();
params.NStory = 6;
params.NBay = 3;
params.NBayZ = 2;
params.dataDir = "Data";

params.runDynamic = true;
params.GMdir = "GMfiles";
params.GMfiles = ["H-E01140", "H-E12140"];
params.GMdirections = [1, 2];
params.GMfactors = [1.5, 0.75];
params.DtAnalysis = 0.005;
params.TmaxAnalysis = 0.005 * 7800;


results = genericFrame3DRCsec(opsMAT, params); %[output:4b53553f]
%%
%[text] 
nodeResp = opsMAT.post.getNodalResponse("MyODB");
%%
%[text] 
%[text] 
figure("Color", "w", "Position", [100, 100, 1300, 800]); %[output:0c7d5131]

fontName = "Times New Roman";
fontSizeMain = 18;
fontSizeSmall = 16;

% Axes positions: [left bottom width height]
% Larger spacing between subplots
posIso = [0.005, 0.045, 0.55, 0.9];

posXY  = [0.65, 0.690, 0.35, 0.2];
posXZ  = [0.65, 0.390, 0.35, 0.2];
posYZ  = [0.65, 0.090, 0.35, 0.2];

viewInfo = {
    "iso", "3D View",       posIso, -37.5, 30
    "xy",  "XY Plan View",  posXY,   0,    90
    "xz",  "XZ Elevation",  posXZ,   0,    0
    "yz",  "YZ Elevation",  posYZ,   90,   0
    };

for i = 1:size(viewInfo, 1)

    ax = axes("Position", viewInfo{i, 3}); %[output:0c7d5131]
    opsvis.plotNodalResponse(nodeResp, ax=ax);

    view(ax, viewInfo{i, 4}, viewInfo{i, 5});

    axis(ax, "equal");
    axis(ax, "tight");
    grid(ax, "on");
    box(ax, "on");

    hTitle = title(ax, viewInfo{i, 2}, ...
    "FontName", fontName, ...
    "FontSize", fontSizeMain, ...
    "FontWeight", "normal");

    % Increase distance between title and model
    hTitle.Units = "normalized";
    hTitle.Position(2) = hTitle.Position(2) + 0.06;

    xlabel(ax, "X", "FontName", fontName);
    ylabel(ax, "Y", "FontName", fontName);
    zlabel(ax, "Z", "FontName", fontName);

    set(ax, ...
        "FontName", fontName, ...
        "FontSize", fontSizeSmall, ...
        "LineWidth", 1.0, ...
        "TickDir", "in");
    axis off;

    if viewInfo{i, 1} == "iso"
        hcb = colorbar;
        hcb.Label.String = "Displacement";
        hcb.Label.FontSize = fontSizeMain; % Optional: change font size
    else
        colorbar(ax,'off');
    end
end
exportgraphics(gcf, fullfile(figureDir, "Frame3D_Disp.pdf"), ...
    "ContentType","vector"); %[output:11c7a1ee] %[output:0c7d5131]

displacementMagnitude = sqrt( ...
    nodeResp.disp.ux.^2 + nodeResp.disp.uy.^2 + nodeResp.disp.uz.^2);
[~, maximumIndex] = max(abs(displacementMagnitude), [], "all", "linear");
[stepIndex, ~] = ind2sub(size(displacementMagnitude), maximumIndex);

nodeTags = double(nodeResp.nodeTags(:));
nodeCoordinates = zeros(numel(nodeTags), 3);
for i = 1:numel(nodeTags)
    nodeCoordinates(i, :) = double(ops.nodeCoord(nodeTags(i)));
end
displacementData = table( ...
    nodeTags, nodeCoordinates(:, 1), nodeCoordinates(:, 2), ...
    nodeCoordinates(:, 3), ...
    nodeResp.disp.ux(stepIndex, :).', ...
    nodeResp.disp.uy(stepIndex, :).', ...
    nodeResp.disp.uz(stepIndex, :).', ...
    repmat(nodeResp.time(stepIndex), numel(nodeTags), 1), ...
    'VariableNames', {'NodeTag','X','Y','Z','UX','UY','UZ','Time_s'});
writetable(displacementData, fullfile(figureDir, "Frame3D_Disp.csv"));
%%
nodeResp = opsMAT.post.getNodalResponse("MyODB");

opsvis.polyscope.plotNodalResponse(nodeResp);
%[text] 
%[text] 
frameResp = opsMAT.post.getElementResponse("MyODB", eleType="Frame");

opsvis.polyscope.plotFrameResponse(frameResp);
